insert into public.bible_verses (id, book_key, book_name, chapter, verse, content, sort_order)
values
('ezk-22-24','ezk','에스겔',22,24,'인자야 너는 그에게 이르기를 너는 정결함을 얻지 못한 땅이요 진노의 날에 비를 얻지 못한 땅이로다 하라',21001),
('ezk-22-25','ezk','에스겔',22,25,'그 가운데에서 선지자들의 반역함이 우는 사자가 음식물을 움킴 같았도다 그들이 사람의 영혼을 삼켰으며 재산과 보물을 탈취하며 과부를 그 가운데에 많게 하였으며',21002),
('ezk-22-26','ezk','에스겔',22,26,'그 제사장들은 내 율법을 범하였으며 나의 성물을 더럽혔으며 거룩함과 속된 것을 구별하지 아니하였으며 부정함과 정한 것을 사람이 구별하게 하지 아니하였으며 그의 눈을 가리어 나의 안식일을 보지 아니하였으므로 내가 그들 가운데에서 더럽힘을 받았느니라',21003),
('ezk-22-27','ezk','에스겔',22,27,'그 가운데에 그 고관들은 음식물을 삼키는 이리 같아서 불의한 이익을 얻으려고 피를 흘려 영혼을 멸하거늘',21004),
('ezk-22-28','ezk','에스겔',22,28,'그 선지자들이 그들을 위하여 회를 칠하고 스스로 허탄한 이상을 보며 거짓 복술을 행하며 여호와가 말하지 아니하였어도 주 여호와께서 이같이 말씀하셨느니라 하였으며',21005),
('ezk-22-29','ezk','에스겔',22,29,'이 땅 백성은 포악하고 강탈을 일삼고 가난하고 궁핍한 자를 압제하고 나그네를 부당하게 학대하였으므로',21006),
('ezk-22-30','ezk','에스겔',22,30,'이 땅을 위하여 성을 쌓으며 성 무너진 데를 막아 서서 나로 하여금 멸하지 못하게 할 사람을 내가 그 가운데에서 찾다가 찾지 못하였으므로',21007),
('ezk-22-31','ezk','에스겔',22,31,'내가 내 분노를 그들 위에 쏟으며 내 진노의 불로 멸하여 그들 행위대로 그들 머리에 보응하였느니라 주 여호와의 말씀이니라',21008),
('ezk-23-1','ezk','에스겔',23,1,'또 여호와의 말씀이 내게 임하여 이르시되',21009),
('ezk-23-2','ezk','에스겔',23,2,'인자야 두 여인이 있었으니 한 어머니의 딸이라',21010),
('ezk-23-3','ezk','에스겔',23,3,'그들이 애굽에서 행음하되 어렸을 때에 행음하여 그들의 유방이 눌리며 그 처녀의 가슴이 어루만져졌나니',21011),
('ezk-23-4','ezk','에스겔',23,4,'그 이름이 형은 오홀라요 아우는 오홀리바라 그들이 내게 속하여 자녀를 낳았나니 그 이름으로 말하면 오홀라는 사마리아요 오홀리바는 예루살렘이니라',21012),
('ezk-23-5','ezk','에스겔',23,5,'오홀라가 내게 속하였을 때에 행음하여 그가 연애하는 자 곧 그의 이웃 앗수르 사람을 사모하였나니',21013),
('ezk-23-6','ezk','에스겔',23,6,'그들은 다 자색 옷을 입은 고관과 감독이요 준수한 청년이요 말 타는 자들이라',21014),
('ezk-23-7','ezk','에스겔',23,7,'그가 앗수르 사람들 가운데에 잘 생긴 그 모든 자들과 행음하고 누구를 연애하든지 그들의 모든 우상으로 자신을 더럽혔으며',21015),
('ezk-23-8','ezk','에스겔',23,8,'그가 젊었을 때에 애굽 사람과 동침하매 그 처녀의 가슴이 어루만져졌으며 그의 몸에 음란을 쏟음을 당한 바 되었더니 그가 그 때부터 행음함을 마지아니하였느니라',21016),
('ezk-23-9','ezk','에스겔',23,9,'그러므로 내가 그를 그의 정든 자 곧 그가 연애하는 앗수르 사람의 손에 넘겼더니',21017),
('ezk-23-10','ezk','에스겔',23,10,'그들이 그의 하체를 드러내고 그의 자녀를 빼앗으며 칼로 그를 죽여 여인들에게 이야깃거리가 되게 하였나니 이는 그들이 그에게 심판을 행함이니라',21018),
('ezk-23-11','ezk','에스겔',23,11,'그 아우 오홀리바가 이것을 보고도 그의 형보다 음욕을 더하며 그의 형의 간음함보다 그 간음이 더 심하므로 그의 형보다 더 부패하여졌느니라',21019),
('ezk-23-12','ezk','에스겔',23,12,'그가 그의 이웃 앗수르 사람을 연애하였나니 그들은 화려한 의복을 입은 고관과 감독이요 말 타는 자들과 준수한 청년이었느니라',21020),
('ezk-23-13','ezk','에스겔',23,13,'그 두 여인이 한 길로 행하므로 그도 더러워졌음을 내가 보았노라',21021),
('ezk-23-14','ezk','에스겔',23,14,'그가 음행을 더하였음은 붉은 색으로 벽에 그린 사람의 형상 곧 갈대아 사람의 형상을 보았음이니',21022),
('ezk-23-15','ezk','에스겔',23,15,'그 형상은 허리를 띠로 동이고 머리를 긴 수건으로 쌌으며 그의 용모는 다 준수한 자 곧 그의 고향 갈대아 바벨론 사람 같은 것이라',21023),
('ezk-23-16','ezk','에스겔',23,16,'그가 보고 곧 사랑하게 되어 사절을 갈대아 그들에게로 보내매',21024),
('ezk-23-17','ezk','에스겔',23,17,'바벨론 사람이 나아와 연애하는 침상에 올라 음행으로 그를 더럽히매 그가 더럽힘을 입은 후에 그들을 싫어하는 마음이 생겼느니라',21025),
('ezk-23-18','ezk','에스겔',23,18,'그가 이같이 그의 음행을 나타내며 그가 하체를 드러내므로 내 마음이 그의 형을 싫어한 것 같이 그를 싫어하였으나',21026),
('ezk-23-19','ezk','에스겔',23,19,'그가 그의 음행을 더하여 젊었을 때 곧 애굽 땅에서 행음하던 때를 생각하고',21027),
('ezk-23-20','ezk','에스겔',23,20,'그의 하체는 나귀 같고 그의 정수는 말 같은 음란한 간부를 사랑하였도다',21028),
('ezk-23-21','ezk','에스겔',23,21,'네가 젊었을 때에 행음하여 애굽 사람에게 네 가슴과 유방이 어루만져졌던 것을 아직도 생각하도다',21029),
('ezk-23-22','ezk','에스겔',23,22,'그러므로 오홀리바야 주 여호와께서 이같이 말씀하셨느니라 나는 네가 사랑하다가 싫어하던 자들을 충동하여 그들이 사방에서 와서 너를 치게 하리니',21030),
('ezk-23-23','ezk','에스겔',23,23,'그들은 바벨론 사람과 갈대아 모든 무리 브곳과 소아와 고아 사람과 또 그와 함께 한 모든 앗수르 사람 곧 준수한 청년이며 다 고관과 감독이며 귀인과 유명한 자요 다 말 타는 자들이라',21031),
('ezk-23-24','ezk','에스겔',23,24,'그들이 무기와 병거와 수레와 크고 작은 방패를 이끌고 투구 쓴 군대를 거느리고 치러 와서 너를 에워싸리라 내가 재판을 그들에게 맡긴즉 그들이 그들의 법대로 너를 재판하리라',21032),
('ezk-23-25','ezk','에스겔',23,25,'내가 너를 향하여 질투하리니 그들이 분내어 네 코와 귀를 깎아 버리고 남은 자를 칼로 엎드러뜨리며 네 자녀를 빼앗고 그 남은 자를 불에 사르며',21033),
('ezk-23-26','ezk','에스겔',23,26,'또 네 옷을 벗기며 네 장식품을 빼앗을지라',21034),
('ezk-23-27','ezk','에스겔',23,27,'이와 같이 내가 네 음란과 애굽 땅에서부터 행음하던 것을 그치게 하여 너로 그들을 향하여 눈을 들지도 못하게 하며 다시는 애굽을 기억하지도 못하게 하리라',21035),
('ezk-23-28','ezk','에스겔',23,28,'주 여호와께서 이같이 말씀하셨느니라 나는 네가 미워하는 자와 네 마음에 싫어하는 자의 손에 너를 붙이리니',21036),
('ezk-23-29','ezk','에스겔',23,29,'그들이 미워하는 마음으로 네게 행하여 네 모든 수고한 것을 빼앗고 너를 벌거벗은 몸으로 두어서 네 음행의 벗은 몸 곧 네 음란하며 행음하던 것을 드러낼 것이라',21037),
('ezk-23-30','ezk','에스겔',23,30,'네가 이같이 당할 것은 네가 음란하게 이방을 따르고 그 우상들로 더럽혔기 때문이로다',21038),
('ezk-23-31','ezk','에스겔',23,31,'네가 네 형의 길로 행하였은즉 내가 그의 잔을 네 손에 주리라',21039),
('ezk-23-32','ezk','에스겔',23,32,'주 여호와께서 이같이 말씀하셨느니라 깊고 크고 가득히 담긴 네 형의 잔을 네가 마시고 코웃음과 조롱을 당하리라',21040),
('ezk-23-33','ezk','에스겔',23,33,'네가 네 형 사마리아의 잔 곧 놀람과 패망의 잔에 넘치게 취하고 근심할지라',21041),
('ezk-23-34','ezk','에스겔',23,34,'네가 그 잔을 다 기울여 마시고 그 깨어진 조각을 씹으며 네 유방을 꼬집을 것은 내가 이렇게 말하였음이라 주 여호와의 말씀이니라',21042),
('ezk-23-35','ezk','에스겔',23,35,'그러므로 주 여호와께서 이같이 말씀하셨느니라 네가 나를 잊었고 또 나를 네 등 뒤에 버렸은즉 너는 네 음란과 네 음행의 죄를 담당할지니라 하시니라',21043),
('ezk-23-36','ezk','에스겔',23,36,'여호와께서 또 내게 이르시되 인자야 네가 오홀라와 오홀리바를 심판하려느냐 그러면 그 가증한 일을 그들에게 말하라',21044),
('ezk-23-37','ezk','에스겔',23,37,'그들이 행음하였으며 피를 손에 묻혔으며 또 그 우상과 행음하며 내게 낳아 준 자식들을 우상을 위하여 화제로 살랐으며',21045),
('ezk-23-38','ezk','에스겔',23,38,'이 외에도 그들이 내게 행한 것이 있나니 당일에 내 성소를 더럽히며 내 안식일을 범하였도다',21046),
('ezk-23-39','ezk','에스겔',23,39,'그들이 자녀를 죽여 그 우상에게 드린 그 날에 내 성소에 들어와서 더럽혔으되 그들이 내 성전 가운데에서 그렇게 행하였으며',21047),
('ezk-23-40','ezk','에스겔',23,40,'또 사절을 먼 곳에 보내 사람을 불러오게 하고 그들이 오매 그들을 위하여 목욕하며 눈썹을 그리며 스스로 단장하고',21048),
('ezk-23-41','ezk','에스겔',23,41,'화려한 자리에 앉아 앞에 상을 차리고 내 향과 기름을 그 위에 놓고',21049),
('ezk-23-42','ezk','에스겔',23,42,'그 무리와 편히 지껄이고 즐겼으며 또 광야에서 잡류와 술 취한 사람을 청하여 오매 그들이 팔찌를 그 손목에 끼우고 아름다운 관을 그 머리에 씌웠도다',21050),
('ezk-23-43','ezk','에스겔',23,43,'내가 음행으로 쇠한 여인을 가리켜 말하노라 그가 그래도 그들과 피차 행음하는도다',21051),
('ezk-23-44','ezk','에스겔',23,44,'그들이 그에게 나오기를 기생에게 나옴 같이 음란한 여인 오홀라와 오홀리바에게 나왔은즉',21052),
('ezk-23-45','ezk','에스겔',23,45,'의인이 간통한 여자들을 재판함 같이 재판하며 피를 흘린 여인을 재판함 같이 재판하리니 그들은 간통한 여자들이요 또 피가 그 손에 묻었음이라',21053),
('ezk-23-46','ezk','에스겔',23,46,'주 여호와께서 이같이 말씀하셨느니라 그가 그들에게 무리를 올려 보내 그들이 공포와 약탈을 당하게 하리니',21054),
('ezk-23-47','ezk','에스겔',23,47,'무리가 그들을 돌로 치며 칼로 죽이고 그 자녀도 죽이며 그 집들을 불사르리라',21055),
('ezk-23-48','ezk','에스겔',23,48,'이같이 내가 이 땅에서 음란을 그치게 한즉 모든 여인이 정신이 깨어 너희 음행을 본받지 아니하리라',21056),
('ezk-23-49','ezk','에스겔',23,49,'그들이 너희 음란으로 너희에게 보응한즉 너희가 모든 우상을 위하던 죄를 담당할지라 내가 주 여호와인 줄을 너희가 알리라 하시니라',21057),
('ezk-24-1','ezk','에스겔',24,1,'아홉째 해 열째 달 열째 날에 여호와의 말씀이 내게 임하여 이르시되',21058),
('ezk-24-2','ezk','에스겔',24,2,'인자야 너는 날짜 곧 오늘의 이름을 기록하라 바벨론 왕이 오늘 예루살렘에 가까이 왔느니라',21059),
('ezk-24-3','ezk','에스겔',24,3,'너는 이 반역하는 족속에게 비유를 베풀어 이르기를 주 여호와께서 이같이 말씀하시기를 가마 하나를 걸라',21060),
('ezk-24-4','ezk','에스겔',24,4,'건 후에 물을 붓고 양 떼에서 한 마리를 골라 각을 뜨고 그 넓적다리와 어깨 고기의 모든 좋은 덩이를 그 가운데에 모아 넣으며 고른 뼈를 가득히 담고 그 뼈를 위하여 가마 밑에 나무를 쌓아 넣고 잘 삶되 가마 속의 뼈가 무르도록 삶을지어다',21061),
('ezk-24-5','ezk','에스겔',24,5,'건 후에 물을 붓고 양 떼에서 한 마리를 골라 각을 뜨고 그 넓적다리와 어깨 고기의 모든 좋은 덩이를 그 가운데에 모아 넣으며 고른 뼈를 가득히 담고 그 뼈를 위하여 가마 밑에 나무를 쌓아 넣고 잘 삶되 가마 속의 뼈가 무르도록 삶을지어다',21062),
('ezk-24-6','ezk','에스겔',24,6,'그러므로 주 여호와께서 이같이 말씀하셨느니라 피를 흘린 성읍, 녹슨 가마 곧 그 속의 녹을 없이하지 아니한 가마여 화 있을진저 제비 뽑을 것도 없이 그 덩이를 하나하나 꺼낼지어다',21063),
('ezk-24-7','ezk','에스겔',24,7,'그 피가 그 가운데에 있음이여 피를 땅에 쏟아 티끌이 덮이게 하지 않고 맨 바위 위에 두었도다',21064),
('ezk-24-8','ezk','에스겔',24,8,'내가 그 피를 맨 바위 위에 두고 덮이지 아니하게 함은 분노를 나타내어 보응하려 함이로라',21065),
